  }
}
const binY = -1.68;
for (let k = 0; k <= rows+1; k++) {
  const bx = centerX + (k-4.5)*spacing;
  scene.add(new Line({ start: [bx, -1.26, 0], end: [bx, binY, 0], color: GRAY }));
}
scene.add(new Line({ start: [centerX-4.5*spacing, binY, 0], end: [centerX+4.5*spacing, binY, 0], color: GRAY }));
for (let k = 0; k <= rows; k++) {
  const label = new Text({ text: String(k), fontSize: 17, color: GRAY });
  label.moveTo([centerX+(k-4)*spacing, -1.92, 0]);
  scene.add(label);
}

const chartLeft = 0.65;
const chartStep = 0.59;
const baseline = -1.65;
const chartHeight = 3.35;
scene.add(new Line({ start: [0.32, baseline, 0], end: [5.72, baseline, 0], color: GRAY }));
scene.add(new Line({ start: [0.32, baseline, 0], end: [0.32, 1.78, 0], color: GRAY }));
const bars = [];
const theoryMarks = [];
