  const mark = new Line({ start: [bx-0.25,baseline,0], end: [bx+0.25,baseline,0], color: GOLD });
  mark.setStrokeWidth(4);
  bars.push(bar);
  theoryMarks.push(mark);
  scene.add(bar, mark);
  const label = new Text({ text: String(k), fontSize: 18, color: GRAY });
  label.moveTo([bx,-1.92,0]);
  scene.add(label);
}
const topValue = new Text({ text: '', fontSize: 16, color: GRAY });
topValue.moveTo([0.03,1.75,0]);
const chartCaption = new Text({ text: 'Probability / observed fraction', fontSize: 20, color: WHITE });
chartCaption.moveTo([3.2,2.12,0]);
const legend = new Text({ text: 'Blue: observed    Gold: binomial', fontSize: 20, color: WHITE });
legend.moveTo([3.2,-2.38,0]);
const readout = new Text({ text: '', fontSize: 21, color: WHITE });
readout.moveTo([3.15,-2.86,0]);
const means = new Text({ text: '', fontSize: 19, color: GRAY });
means.moveTo([3.15,-3.28,0]);
scene.add(topValue, chartCaption, legend, readout, means);

const railLeft = -5.05;
const railRight = -0.95;
const railY = -2.65;
scene.add(new Line({ start: [railLeft,railY,0], end: [railRight,railY,0], color: GRAY }));
const biasHandle = new Dot({ point: [centerX,railY,0], radius: 0.13, color: YELLOW });
const biasLabel = new Text({ text: '', fontSize: 21, color: YELLOW });
biasLabel.moveTo([centerX,-2.25,0]);
const hint = new Text({ text: 'Drag bias • click a drop button', fontSize: 19, color: GRAY });
hint.moveTo([centerX,-3.27,0]);
const leftHint = new Text({ text: 'Left', fontSize: 16, color: GRAY });
leftHint.moveTo([-5.12,-2.99,0]);
const rightHint = new Text({ text: 'Right', fontSize: 16, color: GRAY });
rightHint.moveTo([-0.87,-2.99,0]);
scene.add(biasHandle, biasLabel, hint, leftHint, rightHint);

function update() {
  const expected = choose.map((c,k) => c*Math.pow(probability,k)*Math.pow(1-probability,rows-k));
  const observed = counts.map(c => total ? c/total : 0);
  const ceiling = Math.max(0.35, ...expected, ...observed)*1.08;
  for (let k = 0; k <= rows; k++) {
    const bx = chartLeft+k*chartStep;
    const yObs = baseline+chartHeight*observed[k]/ceiling;
    const yTheory = baseline+chartHeight*expected[k]/ceiling;
    bars[k].setVertices([[bx-0.22,baseline,0],[bx+0.22,baseline,0],[bx+0.22,Math.max(baseline+0.002,yObs),0],[bx-0.22,Math.max(baseline+0.002,yObs),0]]);
    theoryMarks[k].setStart([bx-0.25,yTheory,0]);
    theoryMarks[k].setEnd([bx+0.25,yTheory,0]);
  }
  topValue.setText(ceiling.toFixed(2));
  biasHandle.moveTo([railLeft+(railRight-railLeft)*probability,railY,0]);
  biasLabel.setText('Right-bounce probability p = '+probability.toFixed(2));
  readout.setText('8 rows   •   '+total+' balls collected');
  const sampleMean = total ? counts.reduce((sum,c,k) => sum+c*k,0)/total : null;
  means.setText('Mean: '+(sampleMean === null ? '—' : sampleMean.toFixed(2))+'    Expected: '+(8*probability).toFixed(2));
}
update();

makeDraggable(biasHandle, scene, { onDrag: (mob,pos) => {
  const nextP = Math.max(0,Math.min(1,(pos[0]-railLeft)/(railRight-railLeft)));
  if (Math.abs(nextP-probability)>0.0001) {
    probability = nextP;
    counts = Array(9).fill(0);
    total = 0;
    epoch++;
  }
  update();
} });
const hoverInfo = new Text({ text: 'Changing p clears the old sample', fontSize: 17, color: YELLOW });
hoverInfo.moveTo([centerX,-0.12,0]);
makeHoverable(biasHandle, scene, { onHoverStart: () => scene.add(hoverInfo), onHoverEnd: () => scene.remove(hoverInfo) });

async function dropBalls(amount) {
  if (busy) return;
  busy = true;
  const runEpoch = epoch;
  const runP = probability;
  const progress = new ValueTracker(0);
  const flights = [];
  for (let b = 0; b < amount; b++) {
    let rights = 0;
    const path = [[centerX,2.13,0],[centerX,pegTop+0.08,0]];
    for (let r = 0; r < rows; r++) {
      if (Math.random()<runP) rights++;
      path.push([centerX+(2*rights-(r+1))*spacing/2,pegTop-(r+1)*rowGap+0.08,0]);
    }
    path.push([centerX+(2*rights-rows)*spacing/2,binY+0.08,0]);
    const delay = amount === 1 ? 0 : 0.32*b/(amount-1);
    const ball = new Dot({ point: path[0], radius: amount===1 ? 0.09 : 0.055, color: YELLOW });
    let counted = false;
    ball.addUpdater(mob => {
      const u = Math.max(0,Math.min(1,(progress.getValue()-delay)/(1-delay)));
      const index = u*(path.length-1);
      const i = Math.min(path.length-2,Math.floor(index));
      const f = index-i;
      const a = path[i];
      const z = path[i+1];
      mob.moveTo([a[0]+(z[0]-a[0])*f,a[1]+(z[1]-a[1])*f,0]);
      mob.setOpacity(progress.getValue()<delay ? 0 : 1);
      if (u>=0.999999 && !counted) {
        counted = true;
        if (runEpoch===epoch) { counts[rights]++; total++; update(); }
      }
    });
    flights.push(ball);
    scene.add(ball);
  }
  try {
    await scene.play(progress.animateTo(1));
    for (const ball of flights) scene.remove(ball);
    update();
  } finally { busy = false; }
}

function addDropButton(label, x, amount) {
  const button = new Rectangle({ width: 1.8, height: 0.46, color: BLUE });
  button.setFill(BLUE,0.22);
  button.moveTo([x,2.62,0]);
  const caption = new Text({ text: label, fontSize: 21, color: WHITE });
  caption.moveTo([x,2.62,0]);
  scene.add(button, caption);
  makeClickable(button, scene, { onClick: async () => { await dropBalls(amount); } });
  makeClickable(caption, scene, { onClick: async () => { await dropBalls(amount); } });
}
addDropButton('Drop 1',-4.05,1);
addDropButton('Drop 40',-1.95,40);
